/* Meeting Library UI — static. Never contains data.
 * Reads window.LIBRARY, which data/library.js defines (generated by
 * engine/build_index.py). Same file for every person; replace it to upgrade. */
const SUPPORTED_SCHEMA = 1;
const L = window.LIBRARY;
(function guard(){
  const fail = (h, b) => { document.getElementById('pane').innerHTML =
    `<div class="mhead"><h1>${h}</h1><div class="hint" style="font-size:14px">${b}</div></div>`;
    throw new Error(h); };
  if (!L) fail('No data yet',
    'This page is only the viewer. Build the data next to it:<br><br>'+
    '<code>python3 engine/build_index.py</code><br><br>That writes <code>data/library.js</code>, '+
    'which this page reads. Nothing in the viewer itself holds meeting content.');
  if (L.schema !== SUPPORTED_SCHEMA) fail('Viewer and data are out of step',
    `The data is schema <b>${L.schema}</b>; this viewer reads schema <b>${SUPPORTED_SCHEMA}</b>. `+
    'Update the kit (ui/ and engine/ together), then rebuild.');
})();
const DATA = L.entries, DASH = L.dash, COST = L.cost;
const BUILT = L.built, TITLE = L.title || 'Meeting Library';
document.title = TITLE;
document.getElementById('brand').innerHTML =
  `${esc(TITLE)} <span>${DATA.length} conversations &middot; ${esc(BUILT)}</span>`;
if (L.demo) document.body.classList.add('demo');
const byId = Object.fromEntries(DATA.map(d => [d.id, d]));
const order = DATA.map(d => d.id);
const slist = document.getElementById('slist'), pane = document.getElementById('pane'),
      chipsEl = document.getElementById('chips'), q = document.getElementById('q'),
      side = document.getElementById('side'), main = document.getElementById('main');
let selected = null, facet = null, allActs = false, actOwner = null, view = null;
/* sensitive notes are hidden everywhere (list, search, topics, decisions, actions) until
   shown; the choice is remembered in this browser only */
const SKEY = 'meetinglib.showSens';
let showSens = false;
try { showSens = localStorage.getItem(SKEY) === '1'; } catch(e){}
const LOCK = '<svg class="lock" viewBox="0 0 16 16" width="12" height="12" aria-label="sensitive"><title>Sensitive</title><path fill="currentColor" d="M8 1a3.5 3.5 0 0 0-3.5 3.5V6H4a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1V7a1 1 0 0 0-1-1h-.5V4.5A3.5 3.5 0 0 0 8 1Zm-2 3.5a2 2 0 1 1 4 0V6H6V4.5Z"/></svg>';
const visible = d => !d.sensitive || showSens;
const nSensitive = DATA.filter(d => d.sensitive).length;
function setSens(v){ showSens = v; try { localStorage.setItem(SKEY, v ? '1' : '0'); } catch(e){} render(); }

const PALETTE = ['#cfe3a8','#f2d9a0','#e8c4c0','#c9d8ee','#dfcfe8','#f0d7b4','#bfdcd2','#eccfd8'];
function tint(s){ let h=0; for (const c of s) h = (h*31 + c.charCodeAt(0)) >>> 0;
  return PALETTE[h % PALETTE.length]; }
function esc(s){ return String(s).replace(/[&<>"]/g, c =>
  ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function inl(s){ return esc(s).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>')
  .replace(/`(.+?)`/g,'<code>$1</code>'); }

/* ---- render a Granola enhanced note: # headings, nested bullets ---- */
function renderNote(md){
  const lines = md.split('\n');
  let out = '', depth = 0;
  const close = to => { while (depth > to){ out += '</ul>'; depth--; } };
  for (const raw of lines){
    if (!raw.trim()){ continue; }
    const h = raw.match(/^(#{1,6})\s+(.*)$/);
    if (h){ close(0);
      out += `<div class="h"><span class="hash">#</span><span class="ht">${inl(h[2])}</span></div>`;
      continue; }
    const b = raw.match(/^(\s*)[-*]\s+(.*)$/);
    if (b){
      const want = Math.min(Math.floor(b[1].length / 2) + 1, 3);
      while (depth < want){ out += '<ul>'; depth++; }
      close(want);
      out += `<li>${inl(b[2])}</li>`;
      continue;
    }
    close(0);
    out += `<p>${inl(raw.trim())}</p>`;
  }
  close(0);
  return out;
}

function renderActions(md){
  let out = '';
  for (const raw of md.split('\n')){
    const line = raw.trim();
    if (!line) continue;
    const a = line.match(/^-\s*\[( |x|X)\]\s*(.+)$/);
    if (a){ out += `<div class="it"><span class="box">${a[1].trim() ? '&#10003;' : '&#9744;'}</span>${inl(a[2])}</div>`; continue; }
    out += `<div class="it">${inl(line.replace(/^-\s*/,''))}</div>`;
  }
  return out;
}

/* ---- facets: counted over the meetings you can currently see ---- */
function drawFacets(){
  const tally = {};
  DATA.filter(visible).forEach(d => [...d.people, ...d.mentioned].forEach(p => tally[p] = (tally[p]||0) + 1));
  const facets = Object.entries(tally).filter(([,n]) => n > 1)
    .sort((a,b) => b[1]-a[1] || a[0].localeCompare(b[0])).slice(0,16);
  chipsEl.innerHTML = facets.map(([p,n]) =>
    `<button class="chip" data-facet="${esc(p)}">${esc(p)} ${n}</button>`).join('');
}

function matches(d){
  if (!visible(d)) return false;
  if (facet && ![...d.people, ...d.mentioned].includes(facet)) return false;
  const terms = q.value.toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return true;
  const hay = (d.title+' '+d.full+' '+d.people.join(' ')+' '+d.mentioned.join(' ')+' '+
    d.tags.join(' ')+' '+d.type+' '+d.account).toLowerCase();
  return terms.every(t => hay.includes(t));
}

function sensBar(){
  const srv = window.ML_SERVER ? '' : ' (read-only: start the server to save settings)';
  return `<div class="sbar"><button class="sbtn${showSens ? ' on' : ''}" data-sensall="1" ${nSensitive ? '' : 'disabled'}
      title="Sensitive meetings are hidden until you show them">${LOCK} ${showSens ? 'hide' : 'show'} sensitive (${nSensitive})</button>
    <button class="sbtn${view === 'settings' ? ' on' : ''}" data-settings="1" title="Settings${esc(srv)}">&#9881; Settings${
      L.review && L.review.open ? ` <i class="badge">${L.review.open}</i>` : ''}</button></div>`;
}
function renderSidebar(){
  document.getElementById('sbar').innerHTML = sensBar();
  const hits = DATA.filter(matches);
  if (!hits.length){ slist.innerHTML = '<div class="none">Nothing matches.</div>'; return; }
  let out = '', day = null;
  for (const d of hits){
    if (d.day !== day){ day = d.day; out += `<div class="dgroup">${esc(day)}</div>`; }
    out += `<div class="row${d.id===selected?' on':''}${d.sensitive ? ' sens' : ''}" data-id="${esc(d.id)}">
      <div class="av" style="background:${tint(d.initial+d.title)}">${esc(d.initial)}</div>
      <div class="rtext"><div class="rtitle">${d.sensitive ? LOCK + ' ' : ''}${esc(d.title)}</div>
      ${d.who ? `<div class="rwho">${esc(d.who)}</div>` : ''}</div>
      <div class="rtime">${esc(d.time)}</div></div>`;
  }
  slist.innerHTML = out;
}

function topbar(crumb, prev, next){
  return `<div class="topbar">
    <button class="bk" data-clear="1">&larr; Dashboard</button>
    <div class="bcrumb">${crumb}</div>
    <div class="nav">
      <button class="bk" data-goto="${prev ? esc(prev) : ''}" ${prev ? '' : 'disabled'}
        title="Newer conversation">&uarr;</button>
      <button class="bk" data-goto="${next ? esc(next) : ''}" ${next ? '' : 'disabled'}
        title="Older conversation">&darr;</button>
    </div></div>`;
}

function renderDetail(d){
  const who = [...d.people, ...d.mentioned];
  const i = order.indexOf(d.id);
  pane.innerHTML = topbar(
      `${esc(d.day)}${d.time ? ' &middot; ' + esc(d.time) : ''}`,
      i > 0 ? order[i - 1] : null,
      i > -1 && i < order.length - 1 ? order[i + 1] : null) +
    `<div class="mhead"><div class="ttl"><h1>${esc(d.title)}</h1>
        <button class="bk pdf" data-pdf="${esc(d.id)}" title="Download this note as PDF">&#8595; PDF</button></div>
      <div class="pillrow">
        <span class="gp">&#9998; <b>${esc(d.type)}</b></span>
        ${d.sensitive ? `<span class="gp sensp">${LOCK} <b>sensitive</b></span>` : ''}
        <span class="gp">&#128197; ${esc(d.day)}${d.time ? ' &middot; ' + esc(d.time) : ''}</span>
        ${d.people.length ? `<span class="gp">&#128101; ${esc(d.people.length)}</span>` : ''}
        ${d.account ? `<span class="gp">&#127970; ${esc(d.account)}</span>` : ''}
        ${d.url ? `<a class="gp click" href="${esc(d.url)}" target="_blank" rel="noopener">&#8599; granola</a>` : ''}
        ${d.drive_url ? `<a class="gp click" href="${esc(d.drive_url)}" target="_blank" rel="noopener">&#8599; gemini</a>` : ''}
        ${d.coverage ? `<span class="gp">${esc(d.coverage)}</span>` : ''}
      </div>
      <div class="pills">
        ${who.map(p => `<span class="pill" data-facet="${esc(p)}">${esc(p)}</span>`).join('')}
        ${d.tags.map(t => `<span class="pill tag">#${esc(t)}</span>`).join('')}
      </div><hr class="rule"></div>
    ${d.recall ? `<h2 class="sec">Recall</h2><div class="recall">${esc(d.recall)}</div>` : ''}
    ${d.actions_md ? `<h2 class="sec">Decisions &amp; actions</h2><div class="acts">${renderActions(d.actions_md)}</div>` : ''}
    ${d.note ? `<h2 class="sec">Enhanced note</h2><div class="nb">${renderNote(d.note)}</div>` : ''}
    ${d.private ? `<h2 class="sec">Private notes</h2><div class="priv">${esc(d.private)}</div>` : ''}
    <div class="links"><a href="#" data-clear="1">&larr; dashboard</a>
      <a href="${esc(d.file)}">open .md</a>
      ${window.ML_SERVER ? `<a href="#" data-marksens="${esc(d.id)}" data-val="${d.sensitive ? '0' : '1'}">${
        d.sensitive ? 'remove sensitive mark' : 'mark as sensitive'}</a>` : ''}
      ${d.updated ? `<span style="color:var(--faint)">note last edited ${esc(d.updated.replace('T',' '))}</span>` : ''}
    </div>`;
  main.scrollTop = 0;
}

function renderDash(){
  const c = DASH.counts;
  pane.innerHTML = `<div class="mhead">
      <div class="dtop"><div>
        <h1>${esc(TITLE)}</h1>
        <div class="pillrow">
          <span class="gp">&#128202; <b>Dashboard</b></span>
          <span class="gp">&#128197; rebuilt ${esc(BUILT)}</span>${L.demo ? `<span class="gp">&#9888; <b>demo data</b> &mdash; fictional people and companies</span>` : ''}
        </div>
      </div>${costWidget()}</div>
      <div class="stats">
        <div class="stat"><div class="n">${c.notes}</div><div class="l">conversations</div></div>
        <div class="stat"><div class="n">${c.last30}</div><div class="l">last 30 days</div></div>
        <div class="stat"><div class="n">${c.open}</div><div class="l">open actions</div></div>
        <div class="stat"><div class="n">${c.people}</div><div class="l">people tracked</div></div>
      </div><hr class="rule"></div>

    ${capBanner()}

    <div class="dgrid">
      <section class="dleft">
        <h2 class="sec">Active topics</h2>
        <div class="tgrid">${topicCards()}</div>
        <div class="hint">Ranked by recency and how many people a topic touches &mdash; 14-day half-life, so March noise fades out.</div>
      </section>
      <section class="dright">
        ${decisionsBox()}
        ${openActions()}
      </section>
    </div>

    <h2 class="sec">Who's been coming up</h2>
    <div class="plist">${DASH.people.map(p => `<span class="pbtn" data-facet="${esc(p.name)}">
      ${esc(p.name)} <i>${p.n}</i></span>`).join('')}</div>
    <div class="hint">Weighted toward recent conversations; being in the room counts double being mentioned.</div>`;
  main.scrollTop = 0;
}

/* ---- active topics: 2-up cards, every meeting listed, people kept quiet ---- */
function topicCards(){
  /* a topic is shown with the meetings you can see; if every one is sensitive and hidden, the card goes */
  const list = DASH.topics.map(t => {
    const refs = t.notes.filter(visible);
    return {...t, notes: refs, notes_n: refs.length};
  }).filter(t => t.notes_n).slice(0, 12);
  const max = list.length ? list[0].score : 1;
  if (!list.length) return '<div class="none">No active topics yet.</div>';
  return list.map(t => {
    const lit = Math.max(1, Math.round(t.score / max * 5));
    return `<div class="topic">
      <div class="tt"><span class="nm">${esc(t.tag.replace(/-/g,' '))}</span>
        <span class="dots" title="relative activity">${[0,1,2,3,4].map(i =>
          `<i class="${i < lit ? 'on' : ''}"></i>`).join('')}</span></div>
      <div class="tmeta"><span><b>${t.notes_n}</b> note${t.notes_n>1?'s':''}</span>
        <span><b>${t.people_n}</b> ${t.people_n===1?'person':'people'}</span>
        <span>last ${esc(t.last)}</span></div>
      <div class="refs">${t.notes.map(n =>
        `<div class="ref" data-id="${esc(n.id)}"><span class="t">${n.sensitive ? LOCK + ' ' : ''}${esc(n.title)}</span>
          <em>${esc(n.day)}</em></div>`).join('')}</div>
      ${t.people.length ? `<div class="tppl">${t.people.map(p =>
        `<span class="tp" data-facet="${esc(p)}">${esc(p)}</span>`)
        .join('<span class="sep"> &middot; </span>')}${
        t.people_n > t.people.length ? `<span class="sep"> &middot; </span>+${
        t.people_n - t.people.length}` : ''}</div>` : ''}
      </div>`;
  }).join('');
}

/* ---- decisions: grouped by theme, repeats merged, 8 rows at a time ----
   Groups come from data/groups.json (the grouping step); x hides in this browser only;
   sensitive ones (added by the insights layer from sensitive-tagged notes) sit behind a toggle. */
const DKEY = 'meetinglib.hiddenDecisions';
const decKey = d => d.id + '|' + d.text;            /* same string as engine insights.dkey */
function hiddenSet(){ try { return new Set(JSON.parse(localStorage.getItem(DKEY) || '[]')); }
  catch(e){ return new Set(); } }
function saveHidden(set){ try { localStorage.setItem(DKEY, JSON.stringify([...set])); } catch(e){} }
let allDecs = false, decQ = '';
const openGroups = new Set();
const GROUPS = DASH.dgroups || [];

function decModel(){
  const hidden = hiddenSet(), terms = decQ.toLowerCase().split(/\s+/).filter(Boolean);
  const searching = terms.length > 0;
  const inGroup = new Set(GROUPS.flatMap(g => g.items.flatMap(i => i.keys)));
  const match = hay => terms.every(t => hay.toLowerCase().includes(t));
  let nSens = 0;
  const rows = [];
  GROUPS.forEach((g, gi) => {
    const items = g.items.filter(i => {
      if (i.keys.every(k => hidden.has(k))) return false;
      if (i.sensitive && !showSens){ nSens++; return false; }
      return !searching || match(i.text + ' ' + g.title + ' ' + g.digest + ' ' +
        i.sources.map(x => x.title + ' ' + x.day).join(' '));
    });
    if (items.length) rows.push({type: 'group', g, gi, items, date: g.date});
  });
  DASH.decisions.forEach(d => {
    if (inGroup.has(decKey(d)) || hidden.has(decKey(d))) return;
    if (d.sensitive && !showSens){ nSens++; return; }
    if (searching && !match(d.text + ' ' + d.title + ' ' + d.day)) return;
    rows.push({type: 'one', d, date: d.date});
  });
  rows.sort((x, y) => y.date.localeCompare(x.date) ||
    (y.type === 'group' && y.g.key ? 1 : 0) - (x.type === 'group' && x.g.key ? 1 : 0));
  const n = rows.reduce((a, r) => a + (r.type === 'group' ? r.items.length : 1), 0);
  const nHid = DASH.decisions.filter(d => hidden.has(decKey(d))).length;
  return {rows, n, nSens, nHid, searching};
}
function tagFor(x){
  return x.source === 'claude'
    ? ` <span class="dtag${x.importance >= 3 ? ' key' : ''}" title="${esc(x.evidence || 'Added by the insights layer')}">${
      x.importance >= 3 ? 'key' : 'suggested'}</span>` : '';
}
function srcLine(sources){
  return '&mdash; ' + sources.map(s => `${esc(s.title)}, ${esc(s.day)}`).join(' &middot; ');
}
function delBtn(keys, title){
  return `<button class="dx" data-delkeys="${esc(JSON.stringify(keys))}" title="${esc(title)}">&times;</button>`;
}
function decRow(r, searching){
  if (r.type === 'one'){
    const d = r.d;
    return `<div class="ditem" data-id="${esc(d.id)}">
      <span class="tx">${d.sensitive ? LOCK + ' ' : ''}${inl(d.text)}${tagFor(d)} <span class="src">${srcLine([d])}</span></span>
      ${delBtn([decKey(d)], 'Hide: not interested or obsolete')}</div>`;
  }
  const open = searching || openGroups.has(r.gi), g = r.g;
  const meetings = new Set(r.items.flatMap(i => i.sources.map(s => s.id))).size;
  return `<div class="dgrp${open ? ' open' : ''}">
    <div class="dgh" data-gtoggle="${r.gi}">
      <span class="chev">${open ? '&#9662;' : '&#9656;'}</span>
      <span class="gt">${r.items.every(i => i.sensitive) ? LOCK + ' ' : ''}${esc(g.title)}</span>${g.key ? ' <span class="dtag key">key</span>' : ''}${
        g.note ? ' <span class="gwarn" title="' + esc(g.note) + '">&#9888;</span>' : ''}
      <span class="gcount">${r.items.length} decision${r.items.length > 1 ? 's' : ''}${
        meetings > 1 ? ' &middot; ' + meetings + ' meetings' : ''}</span>
      ${delBtn(r.items.flatMap(i => i.keys), 'Hide this whole group')}
    </div>
    ${g.digest ? `<div class="gdig">${esc(g.digest)}</div>` : ''}
    ${open ? `<div class="gitems">${r.items.map(i => `<div class="ditem gi" data-id="${esc(i.sources[0].id)}">
        <span class="tx">${i.sensitive ? LOCK + ' ' : ''}${inl(i.text)}${tagFor(i)} <span class="src">${srcLine(i.sources)}</span></span>
        ${delBtn(i.keys, 'Hide this decision')}</div>`).join('')}
      ${g.note ? `<div class="gnote">&#9888; ${esc(g.note)}</div>` : ''}</div>` : ''}</div>`;
}
function decBody(){
  const {rows, nSens, searching} = decModel();
  if (!rows.length) return `<div class="none">${searching ? 'No decision matches.' : 'None recorded yet.'}</div>` + decFoot(nSens, 0, searching);
  const shown = (allDecs || searching) ? rows : rows.slice(0, 8);
  return `<div class="dlist">${shown.map(r => decRow(r, searching)).join('')}</div>` +
    decFoot(nSens, rows.length, searching);
}
function decFoot(nSens, total, searching){
  const more = !searching && total > 8
    ? `<button class="more" data-decs="1">${allDecs ? '&minus; show fewer' : '+ view the other ' + (total - 8)}</button>` : '';
  const sens = (nSens || showSens)
    ? `<button class="more" data-sensall="1">${showSens ? 'hide sensitive' : 'show sensitive (' + nSens + ')'}</button>` : '';
  return (more || sens) ? `<div class="dfoot">${more}${sens}</div>` : '';
}
function decCount(){
  const {n, searching} = decModel();
  return searching ? `${n} found` : `${n} decisions`;
}
function decisionsBox(){
  const {n, nHid, nSens} = decModel();
  if (!DASH.decisions.length)
    return `<h2 class="sec">Decisions</h2><div class="hint">None recorded yet.</div>`;
  return `<h2 class="sec">Decisions</h2>
    <div class="box">
      <div class="bhead"><span class="bt">All meetings</span>
        <span class="bn" id="dcount">${decCount()}</span>
        <input id="dq" class="dsearch" placeholder="Search decisions&hellip;" value="${esc(decQ)}" autocomplete="off">${nHid
          ? `<a class="restore" href="#" data-restoredec="1">restore ${nHid}</a>` : ''}</div>
      <div id="dbody">${decBody()}</div>
    </div>`;
}

/* ---- open actions: one boxed section, filterable, 10 at a time ---- */
function openActions(){
  const all = DASH.open.filter(visible);
  if (!all.length)
    return `<h2 class="sec">Open actions</h2><div class="hint">Nothing outstanding.</div>`;
  const cnt = {};
  all.forEach(a => { const k = a.owner || 'Unassigned'; cnt[k] = (cnt[k] || 0) + 1; });
  const owners = Object.entries(cnt).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 5).map(([owner, n]) => ({owner, items: {length: n}}));
  const list = actOwner ? all.filter(a => (a.owner || 'Unassigned') === actOwner) : all;
  const shown = allActs ? list : list.slice(0, 10);
  return `<h2 class="sec">Open actions</h2>
    <div class="box">
      <div class="bhead"><span class="bt">${actOwner ? esc(actOwner) : 'Everyone'}</span>
        <span class="bn">${list.length} open</span>
        <div class="bfil">${owners.map(o => `<button class="of${
          actOwner === o.owner ? ' on' : ''}" data-owner="${esc(o.owner)}"
          >${esc(o.owner.split(' ')[0])} ${o.items.length}</button>`).join('')}</div>
      </div>
      <div class="olist">${shown.map(a => `<div class="oitem" data-id="${esc(a.id)}">
        <span class="bx">&#9744;</span><span class="tx">${a.sensitive ? LOCK + ' ' : ''}${inl(a.what)}</span>
        ${!actOwner && a.owner ? `<span class="oown">${esc(a.owner.split(' ')[0])}</span>` : ''}
        <span class="src">${esc(a.day)}</span></div>`).join('')}</div>
      ${list.length > 10 ? `<button class="more" data-acts="1">${allActs
        ? '&minus; show fewer' : '+ view the other ' + (list.length - 10)}</button>` : ''}
    </div>`;
}

/* ---- running cost, computed at build time from ops/sync-log.jsonl ---- */
function costWidget(){
  if (!COST || !COST.available)
    return `<aside class="widget"><div class="wh">Running cost</div>
      <div class="wnote" style="border:0;margin-top:7px;padding:0">${
      esc(COST && COST.why || 'No sync runs logged yet.')}</div></aside>`;
  const usd = n => '$' + n.toFixed(2);
  const last = COST.months[COST.months.length - 1];
  const per = last.runs ? last.usd / last.runs : 0;
  return `<aside class="widget">
    <div class="wh">Running cost</div>
    <div class="wbig">${usd(COST.total_usd)}</div>
    <div class="wsub">estimated, ${COST.runs} sync run${COST.runs === 1 ? '' : 's'}</div>
    <div class="wrows">
      <div><span>${esc(last.label)}</span><b>${usd(last.usd)}</b></div>
      <div><span>per run</span><b>${usd(per)}</b></div>
      <div><span>quiet runs</span><b>${COST.empty} of ${COST.runs}</b></div>
      <div><span>tokens</span><b>${Math.round(COST.tokens / 1000)}k</b></div>
    </div>
    ${capMeter()}
    ${COST.alerts.length
      ? `<div class="walert"><b>${COST.alerts.length} alert${
          COST.alerts.length > 1 ? 's' : ''}</b> &mdash; ${esc(COST.alerts[0])}</div>`
      : `<div class="wok">No alerts &mdash; nothing is running away.</div>`}
    <div class="wfoot"><code>ops/cost_report.py</code> for the full breakdown</div>
  </aside>`;
}

/* ---- monthly cap: meter in the widget, banner above the table ---- */
function capMeter(){
  const b = COST && COST.budget;
  if (!b || !b.enabled) return '';
  const usd = n => '$' + n.toFixed(2);
  const pct = Math.min(1, b.used);
  const cls = b.over ? ' over' : (b.used >= 0.8 ? ' warn' : '');
  return `<div class="wcap">
      <div class="wcapr"><span>${esc(b.label)} cap</span>
        <b>${usd(b.spent)} / ${usd(b.cap)}</b></div>
      <div class="meter${cls}"><i style="width:${(pct * 100).toFixed(1)}%"></i></div>
    </div>
    ${b.over ? `<div class="wover"><b>Over the monthly cap</b>
      Scheduled syncing is paused until ${esc(b.label)} rolls over. A manual run
      can still override it.</div>` : ''}`;
}

function capBanner(){
  const b = COST && COST.budget;
  if (!b || !b.enabled || !b.over) return '';
  const usd = n => '$' + n.toFixed(2);
  return `<div class="capban">
    <div class="cb1"><i>&#9888;</i>Monthly cost cap exceeded &mdash; syncing paused</div>
    ${esc(b.label)} is at <b>${usd(b.spent)}</b> of the <b>${usd(b.cap)}</b> cap
    across ${b.runs} run${b.runs === 1 ? '' : 's'}. The sync will refuse to fetch
    until the 1st, when the cap resets on its own.
    <div class="cbsub">Granola's free plan keeps 30 days, so a long pause loses
      history. To fetch anyway, ask Claude to &ldquo;sync the meeting library anyway&rdquo;, or raise
      <code>monthly_budget_usd</code> in <code>ops/rates.json</code>.
      This caps an estimate, not a bill &mdash; scheduled runs draw on the Claude plan.</div>
  </div>`;
}

function renderPane(){
  /* the dashboard gets the wide two-column canvas; every other view keeps the reading width */
  pane.classList.toggle('wide', !(selected && byId[selected]) && !q.value && !facet);
  if (view === 'settings' && typeof renderSettings === 'function') return renderSettings(pane);
  if (selected && byId[selected]) return renderDetail(byId[selected]);
  if (!q.value && !facet) return renderDash();
  const hits = DATA.filter(matches);
  pane.innerHTML = topbar(facet ? 'filtered by person' : 'search results', null, null) +
    `<div class="mhead"><h1>${facet ? esc(facet) : 'Search'}</h1>
      <div class="pillrow"><span class="gp">${hits.length} ${hits.length===1?'entry':'entries'}</span>
      <span class="gp click" data-clear="1">&times; clear</span></div><hr class="rule"></div>` +
    hits.map(d => `<div class="card" data-id="${esc(d.id)}"><h3>${esc(d.title)}</h3>
      <div class="cmeta">${esc(d.day)}${d.time?' &middot; '+esc(d.time):''} &middot; ${esc(d.type)}</div>
      <div class="csnip">${esc(d.recall)}</div></div>`).join('');
  main.scrollTop = 0;
}

function render(){
  drawFacets();
  renderSidebar();
  [...chipsEl.children].forEach(c => c.classList.toggle('on', c.dataset.facet === facet));
  renderPane();
}

/* ---- routing: the hash is the state, so Back works (file:// safe) ---- */
async function markSensitive(id, val){
  try { await mlApi('/api/sensitive', {id, value: val}); location.reload(); }
  catch(err){ alert(err.message); }
}
function hashFor(){
  if (selected) return '#n/' + encodeURIComponent(selected);
  if (facet)    return '#p/' + encodeURIComponent(facet);
  return '';
}
function go(h){                       /* new history entry → Back returns here */
  if ((location.hash || '') === h) return render();
  location.hash = h;                  /* hashchange does the rendering */
}
function applyHash(){
  const h = decodeURIComponent(location.hash.slice(1));
  selected = facet = null; view = null;
  if (h === 'settings' || h.startsWith('settings/')) { view = 'settings'; q.value = ''; }
  else if (h.startsWith('n/') && byId[h.slice(2)]) selected = h.slice(2);
  else if (h.startsWith('p/')) { facet = h.slice(2); q.value = ''; }
  render();
}
window.addEventListener('hashchange', applyHash);

/* ---- download as PDF: the browser's print engine renders the note exactly as
   styled (vector text, real links); @media print in app.css strips the chrome.
   The document title becomes the suggested PDF filename. ---- */
function downloadPdf(id){
  const d = byId[id]; if (!d) return;
  const prev = document.title;
  document.title = `${d.day} - ${d.title}`.replace(/[\/\\:*?"<>|]+/g, '-');
  const restore = () => { document.title = prev; window.removeEventListener('afterprint', restore); };
  window.addEventListener('afterprint', restore);
  window.print();
  setTimeout(restore, 1000);   /* fallback for browsers without afterprint */
}

document.addEventListener('click', e => {
  const pdf = e.target.closest('[data-pdf]');
  if (pdf){ downloadPdf(pdf.dataset.pdf); return; }
  if (e.target.closest('[data-clear]')){ e.preventDefault();
    q.value = ''; go(''); return; }
  const dd = e.target.closest('[data-delkeys]');
  if (dd){ e.preventDefault(); e.stopPropagation(); const h = hiddenSet();
    try { JSON.parse(dd.dataset.delkeys).forEach(k => h.add(k)); } catch(err){}
    saveHidden(h); render(); return; }
  const gt = e.target.closest('[data-gtoggle]');
  if (gt){ const i = +gt.dataset.gtoggle;
    openGroups.has(i) ? openGroups.delete(i) : openGroups.add(i);
    document.getElementById('dbody').innerHTML = decBody(); return; }
  if (e.target.closest('[data-sensall]')){ setSens(!showSens); return; }
  if (e.target.closest('[data-settings]')){ go(view === 'settings' ? '' : '#settings'); return; }
  const ms = e.target.closest('[data-marksens]');
  if (ms){ e.preventDefault(); markSensitive(ms.dataset.marksens, ms.dataset.val === '1'); return; }
  if (e.target.closest('[data-restoredec]')){ e.preventDefault(); saveHidden(new Set()); render(); return; }
  const dg = e.target.closest('[data-decs]');
  if (dg){ allDecs = !allDecs; document.getElementById('dbody').innerHTML = decBody(); return; }
  const ag = e.target.closest('[data-acts]');
  if (ag){ allActs = !allActs; render(); return; }
  const ow = e.target.closest('[data-owner]');
  if (ow){ actOwner = actOwner === ow.dataset.owner ? null : ow.dataset.owner;
    allActs = false; render(); return; }
  const g = e.target.closest('[data-goto]');
  if (g){ if (g.dataset.goto) go('#n/' + encodeURIComponent(g.dataset.goto)); return; }
  const f = e.target.closest('[data-facet]');
  if (f){ const want = facet === f.dataset.facet ? '' : '#p/' + encodeURIComponent(f.dataset.facet);
    q.value = ''; go(want); return; }
  const row = e.target.closest('[data-id]');
  if (row){ side.classList.remove('open'); go('#n/' + encodeURIComponent(row.dataset.id)); }
});

document.addEventListener('input', e => {       /* search the Decisions box without a full re-render */
  if (e.target.id !== 'dq') return;
  decQ = e.target.value;
  document.getElementById('dbody').innerHTML = decBody();
  document.getElementById('dcount').textContent = decCount();
});
document.getElementById('menu').onclick = () => side.classList.toggle('open');
q.oninput = () => {                   /* typing leaves the current view, no history spam */
  if (selected || facet || view){ selected = facet = null; view = null;
    if (location.hash){ go(''); return; } }
  render();
};
document.addEventListener('keydown', e => {
  if (e.key === '/' && !/^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName)){ e.preventDefault(); q.focus(); }
  if (e.key === 'Escape'){ q.value = ''; go(''); }
});

applyHash();
